/* Know Your Candidate - one state's page, and the directory of states.
 *
 * The page is generated by kyc/pages.py with nothing in it but the state
 * code; everything a reader sees is rendered here from the same profiles.js
 * the grid and the map load, so a state page can never disagree with them
 * about who represents a district. Which page this is comes from
 * <body data-page="state" data-state="TX"> or <body data-page="states">.
 */
(function (global) {
  "use strict";

  var doc = global.document;
  var KYC = global.KYC;
  var data = global.legislatorsData || [];
  var races = global.kycRaces || [];
  var cards = KYC.cards;

  var code = doc.body.getAttribute("data-state") || "";
  var kind = doc.body.getAttribute("data-page") || "state";

  function el(id) {
    return doc.getElementById(id);
  }

  function plural(n, word, words) {
    return n + " " + (n === 1 ? word : (words || word + "s"));
  }

  /* ------------------------------------------------------------ one state */

  function peopleIn(race) {
    return race.incumbentIds.concat(race.candidateIds).map(KYC.byId).filter(Boolean);
  }

  function districtLabel(race) {
    if (race.chamber === "Senate") return "U.S. Senate";
    if (!race.district) return "At-large seat";
    return "District " + race.district;
  }

  /* How to vote here: the state's own pages, as the secretaries of state's
   * association lists them (kyc/voting.py). Nothing on the site said how,
   * when or where to vote. No date or deadline is typed here - those are on
   * the state's pages, and they change. NASS covers the 50 states and D.C.,
   * so a territory shows nothing rather than a guess. */
  var VOTING = [
    ["status", "Check your registration"],
    ["polling", "Find your polling place"],
    ["absentee", "Vote absentee or early"],
    ["register", "Register to vote"],
  ];
  function votingBlock(code, name) {
    var all = KYC.meta().voting || {};
    var links = all[code];
    if (!links) return "";
    // A per-state label where NASS's kind does not fit the state: North
    // Dakota does not register voters (overrides.VOTING_LINKS).
    var labels = (all._labels || {})[code] || {};
    var place = code === "DC" ? "the District of Columbia" : name;
    var dated = all._listed
      ? " (listed " + KYC.escapeHtml(all._listed) +
        (all._opened ? "; each link opened " + KYC.escapeHtml(all._opened) : "") + ")"
      : "";
    return '<section class="state-section vote-box" id="voting" aria-labelledby="votingHead">' +
      '<h2 class="state-heading" id="votingHead">' + KYC.icon("vote") + " Voting in " +
        KYC.escapeHtml(place) + "</h2>" +
      '<p class="state-links">' + VOTING.filter(function (v) { return links[v[0]]; }).map(function (v) {
        return '<a class="btn" target="_blank" rel="noopener noreferrer" href="' +
          KYC.escapeAttr(links[v[0]]) + '">' + KYC.icon("link") + " " +
          KYC.escapeHtml(labels[v[0]] || v[1]) + "</a>";
      }).join(" ") + "</p>" +
      '<p class="state-note">Each link is ' + KYC.escapeHtml(KYC.possessive(place)) + " own official page, " +
        "from the National Association of Secretaries of State’s " + '<a href="' +
        KYC.escapeAttr(all._source || "https://www.nass.org/can-I-vote") + '" target="_blank" ' +
        'rel="noopener noreferrer">Can I Vote</a>' + dated +
        ". Deadlines, hours and ID rules are on those pages.</p>" +
      "</section>";
  }

  /* A non-voting member's title, as summary.py gives it: Puerto Rico's
   * Resident Commissioner is not a "delegate". */
  function delegateTitle(info) {
    return info.delegateTitle || "Delegate";
  }

  /* Who holds the state's seats, in words: the hero and the directory of
   * states say it the same way. */
  function seatWords(info) {
    var seats = [];
    if (info.senators) seats.push(plural(info.senators, "senator"));
    if (info.house) seats.push(plural(info.house, "representative"));
    if (info.delegates) {
      var title = delegateTitle(info);
      seats.push(plural(info.delegates, title === "Delegate" ? "delegate" : title));
    }
    return seats;
  }

  /* A House seat elected for longer than two years and not on this
   * cycle's ballot (Puerto Rico's): why it has no race, in place of the
   * zeros. */
  function offCycle(info) {
    var term = info.houseTerm;
    if (!term || info.races) return "";
    return delegateTitle(info) + ": a " + term.years + "-year term, next on the ballot in " + term.next;
  }

  function summaryStrip(info) {
    var parts = seatWords(info);
    if (offCycle(info)) {
      parts.push(offCycle(info));
      return badges(parts);
    }
    // Once the new Congress sits these are a record of 2026, and say so.
    var rec = KYC.recordPhase();
    parts.push(plural(info.seatsUp, "seat") + " in Congress on the 2026 ballot");
    if (info.open) parts.push(plural(info.open, "open seat") + (rec ? " in 2026" : ""));
    if (info.renumbered) {
      parts.push(plural(info.renumbered, "member") + " running under a new district number");
    }
    parts = parts.concat(challengerWords(info, rec));
    if (info.challengersOut) {
      parts.push(plural(info.challengersOut, "challenger") + " out after the " +
        (rec ? "2026 " : "") + "primaries");
    }
    return badges(parts);
  }

  /* Who is running against the seats' holders, as the races count them:
   * on the ballot, and - where there is no primary and no ballot has been
   * read (a territory before its list is published) - filed, which is not
   * the same claim. American Samoa read "0 challengers on the ballot" over
   * six filers and a race card saying so. */
  function challengerWords(info, rec) {
    var out = [];
    if (info.challengersOnBallot || !info.challengersFiled) {
      out.push(plural(info.challengersOnBallot, "challenger") +
        (rec ? " on the 2026 ballot" : " on the ballot"));
    }
    if (info.challengersFiled) {
      out.push(plural(info.challengersFiled, "challenger") + " filed; ballot not yet published");
    }
    return out;
  }

  function badges(parts) {
    return parts.map(function (t) {
      return '<span class="badge badge-neutral">' + KYC.escapeHtml(t) + "</span>";
    }).join(" ");
  }

  /* The delegation by party. *vacant* is the state's empty seats, which
   * have no profile to count (summary.py counts them from the races), so
   * the heading agrees with the sidebar. */
  function balance(people, vacant) {
    var counts = { vacant: vacant || 0 };
    people.forEach(function (p) {
      var key = KYC.partyKey(p);
      counts[key] = (counts[key] || 0) + 1;
    });
    var order = [["r", "R"], ["d", "D"], ["i", "I"], ["vacant", "Vacant"]];
    return order.filter(function (o) { return counts[o[0]]; }).map(function (o) {
      return '<span class="party-' + o[0] + '">' + counts[o[0]] + " " + o[1] + "</span>";
    }).join('<span class="sep">/</span>');
  }

  /* The government section's name, for its heading and its jump chip
   * alike: D.C.'s is a local government, a territory's territorial. */
  function govHeading(info) {
    return code === "DC" ? "Local government" : info.territory ? "Territorial government" : "State government";
  }

  function renderState() {
    var target = el("stateContent");
    var info = (KYC.meta().states || {})[code];
    if (!info) {
      target.innerHTML = '<div class="empty-state"><h3>No such state</h3>' +
        "<p>Nothing in the data is filed under " + KYC.escapeHtml(code) + ".</p></div>";
      return;
    }
    var name = info.name;
    doc.title = name + " — Know Your Candidate";
    // Every state links to its district map; a redrawn one says so.
    var districtMap = (KYC.meta().districtMaps || {})[code];

    // Who represents the state now (rule 27): never a former member.
    var members = data.filter(function (p) { return KYC.seated(p) && p.state === code; });
    var senators = members.filter(function (p) { return p.chamber.indexOf("Senate") !== -1; });
    var house = members.filter(function (p) { return p.chamber.indexOf("House") !== -1; })
      .sort(function (a, b) { return KYC.districtOrder(a) - KYC.districtOrder(b); });

    var stateRaces = races.filter(function (r) { return r.state === code; });
    var senateRaces = stateRaces.filter(function (r) { return r.chamber === "Senate"; });
    var houseRaces = stateRaces.filter(function (r) { return r.chamber === "House"; })
      .sort(function (a, b) { return (a.district || 0) - (b.district || 0); });

    var html = [];
    html.push(
      '<header class="state-hero">',
      '<p class="state-kicker">State &amp; territory pages</p>',
      '<h1 class="state-title">' + KYC.escapeHtml(name) + "</h1>",
      '<p class="state-summary">' + summaryStrip(info) + "</p>",
      '<p class="state-links">',
      '<a class="btn" href="' + KYC.escapeAttr(KYC.siteRoot() + "map.html#/?state=" + code) + '">' +
        KYC.icon("map") + " See on the map</a> ",
      '<a class="btn" href="' + KYC.escapeAttr(KYC.siteRoot() + "index.html#/?state=" + code) + '">' +
        KYC.icon("grid") + " All " + KYC.escapeHtml(name) + " profiles</a>",
      districtMap
        ? ' <a class="btn" href="' + KYC.escapeAttr(KYC.siteRoot() + districtMap.page) + '">' +
          KYC.icon("layers") + (districtMap.redrawn ? " Old and new district lines" :
            " District map") + "</a>"
        : "",
      // Every state - not D.C. or a territory - has a legislature page.
      info.senators
        ? ' <a class="btn" href="' + KYC.escapeAttr(KYC.siteRoot() + "legislature/" +
          code.toLowerCase() + ".html") + '">' + KYC.icon("landmark") + " State legislature</a>" +
          ' <a class="btn" href="' + KYC.escapeAttr(KYC.siteRoot() + "counties/" +
          code.toLowerCase() + ".html") + '">' + KYC.icon("layers") + " Counties &amp; local governments</a>" +
          ' <a class="btn" href="' + KYC.escapeAttr(KYC.siteRoot() + "government/states.html") + '">' +
          KYC.icon("scroll") + " How states are governed</a>"
        : "",
      "</p>",
      "</header>"
    );
    /* Where each part of the page starts. On a phone Texas's House
     * delegation alone is 6,500px of cards, and the 2026 races began eleven
     * screens down with the only way to them inside the closed drawer. */
    var parts = [
      senators.length ? ["senators", "U.S. senators"] : null,
      house.length ? ["delegation", info.territory ? delegateTitle(info) : "House delegation"] : null,
      KYC.stategov && (KYC.stategov.state(code) || code === "DC") ? ["state-government", govHeading(info)] : null,
      senateRaces.length + houseRaces.length ? ["races", "2026 races"] : null,
    ].filter(Boolean);
    if (parts.length > 1) {
      html.push('<nav class="toolbar jump-row state-parts" aria-label="On this page">' +
        parts.map(function (p) {
          return '<a class="chip chip-link" href="#' + p[0] + '">' + KYC.escapeHtml(p[1]) + "</a>";
        }).join("") + "</nav>");
    }

    html.push(votingBlock(code, name));

    /* Who holds the seats now. Senators first, then the House by district;
     * a reader who asked "who represents me" gets the answer before the
     * page turns to who is running (rule 27). */
    if (senators.length) {
      html.push(
        '<section class="state-section" id="senators">',
        '<h2 class="state-heading">U.S. senators <span class="balance">' + balance(senators) + "</span></h2>",
        '<div class="card-grid">' + senators.map(cards.card).join("") + "</div>",
        "</section>"
      );
    }
    if (house.length) {
      html.push(
        '<section class="state-section" id="delegation">',
        '<h2 class="state-heading">' + (info.territory ? KYC.escapeHtml(delegateTitle(info)) +
          " to the U.S. House" : "U.S. House delegation") +
          ' <span class="balance">' + balance(house,
            ((info.balance || {}).house || {}).vacant) + "</span></h2>",
        offCycle(info)
          ? '<p class="state-note">' + KYC.escapeHtml(name) + " elects its " +
            KYC.escapeHtml(delegateTitle(info)) + " at large for a " + info.houseTerm.years +
            '-year term (<a href="https://www.law.cornell.edu/uscode/text/48/891" target="_blank" ' +
            'rel="noopener noreferrer">48 U.S.C. § 891</a>). The seat was last on the ballot in ' +
            info.houseTerm.last + " and is next in " + info.houseTerm.next + ", so no seat in Congress " +
            "is on " + KYC.escapeHtml(KYC.possessive(name)) + " 2026 ballot.</p>"
          : "",
        // Each empty seat: who left, when, and whether a special election
        // has been called (summary.py, overrides.SEAT_VACANCIES).
        (info.vacancies || []).map(function (v) {
          return '<p class="state-note">District ' + v.district + ": " +
            KYC.escapeHtml(KYC.vacancyNote(v)) + "</p>";
        }).join(""),
        '<div class="card-grid">' + house.map(cards.card).join("") + "</div>",
        "</section>"
      );
    }

    /* Who runs the state itself: drawn by the module the map's state views
     * use, so the two say the same thing. */
    if (KYC.stategov && (KYC.stategov.state(code) || code === "DC")) {
      html.push(
        '<section class="state-section" id="state-government">',
        '<h2 class="state-heading">' + govHeading(info) + "</h2>",
        '<div class="stategov">' + KYC.stategov.render(code, { links: false }) + "</div>",
        "</section>"
      );
    }

    /* The 2026 races, one section each, in ballot order. */
    var raceHtml = senateRaces.concat(houseRaces).map(function (race) {
      var people = peopleIn(race);
      return cards.raceSection(race, people, { title: districtLabel(race), stateLink: false,
                                               fullOdds: true });
    }).join("");
    if (raceHtml) {
      /* Texas has 38 districts; a row of jump chips saves the scroll. */
      var jumps = senateRaces.concat(houseRaces).map(function (race) {
        var short = race.chamber === "Senate" ? "Senate" : (race.district ? String(race.district) : "At-large");
        return '<a class="chip chip-link" href="#' + KYC.escapeAttr("race-" + race.id) + '" title="' +
          KYC.escapeAttr(districtLabel(race)) + '">' + KYC.escapeHtml(short) + "</a>";
      }).join("");
      html.push(
        '<section class="state-section" id="races">',
        // Congress only, and it says so: a list that looked like the whole
        // ballot left out the governor, the legislature and every local race.
        '<h2 class="state-heading">2026 races for Congress in ' + KYC.escapeHtml(name) + "</h2>",
        '<p class="state-note">Each seat with the sitting member, everyone on the ' +
          "November ballot, and - folded under the race - everyone no longer running. " +
          alsoOnBallot(code, name, info.territory) + "</p>",
        (senateRaces.length + houseRaces.length > 3
          ? '<nav class="toolbar jump-row" aria-label="Jump to a race">' + jumps + "</nav>"
          : ""),
        raceHtml,
        "</section>"
      );
    }

    target.innerHTML = html.join("");
  }

  /** What else the state's November 3 ballot elects, from the same table the
   *  State government section marks, in a sentence. This site lists the
   *  candidates for Congress only, and says so. */
  function alsoOnBallot(code, name, territory) {
    var list = KYC.stategov ? KYC.stategov.ballotList(code) : null;
    var rest = "special elections for vacant seats, other statewide, judicial and local " +
      "contests, and ballot measures, which this site does not list";
    if (code === "DC") {
      // D.C. has no governor or legislature; its own offices, as the D.C.
      // Board of Elections lists them for 2026 (candidate list, July 2026).
      return "Your ballot may also hold the District's own contests, such as for mayor, attorney " +
        "general, the D.C. Council, the State Board of Education and Advisory Neighborhood " +
        "Commissions, which this site does not list (" +
        '<a href="https://www.dcboe.org/elections/2026-elections" target="_blank" ' +
        'rel="noopener noreferrer">D.C. Board of Elections</a>).';
    }
    if (list === null) {
      return territory
        ? "Your ballot may also hold territorial and local contests, such as for governor " +
          "and the legislature, which this site does not list."
        : "Your ballot may also hold local contests, which this site does not list.";
    }
    if (!list) {
      return "None of " + KYC.escapeHtml(KYC.possessive(name)) + " governor, lieutenant governor, attorney " +
        "general, secretary of state or regular legislative seats is elected in 2026; the " +
        "ballot may still hold " + rest + ".";
    }
    return "Of the state offices this site covers, the same ballot also elects " +
      KYC.escapeHtml(list) + " (see " +
      '<a class="state-jump" href="#state-government">State government</a>). It may also hold ' +
      rest + ". This site lists the candidates for Congress only.";
  }

  /* A link to a section of this page ("#state-government", from the guide)
   * arrives before the script has drawn that section, so the browser's own
   * jump finds nothing. Jump once it is there, then drop the fragment: left
   * in the address, closing a profile returned to it and jumped the reader
   * back to the section, however far they had read on. */
  function jumpToSection() {
    var hash = global.location.hash;
    if (!/^#[A-Za-z][\w-]*$/.test(hash)) return;
    var section = doc.getElementById(hash.slice(1));
    if (!section) return;
    if (section.scrollIntoView) section.scrollIntoView({ block: "start" });
    if (global.history && global.history.replaceState) {
      global.history.replaceState(global.history.state, "", global.location.pathname + global.location.search);
    }
  }

  /* ---------------------------------------------------------- all states */

  function renderIndex() {
    var target = el("stateContent");
    var states = KYC.meta().states || {};
    var codes = Object.keys(states).sort(function (a, b) {
      return states[a].name.localeCompare(states[b].name);
    });
    doc.title = "States & territories — Know Your Candidate";

    var rows = codes.map(function (c) {
      var info = states[c];
      var seats = seatWords(info);
      var off = offCycle(info);
      return [
        '<a class="state-row" href="' + KYC.escapeAttr(KYC.stateUrl(c)) + '" data-state="' + KYC.escapeAttr(c) + '">',
        '<span class="state-row-name">' + KYC.escapeHtml(info.name) +
          ' <span class="state-row-code">' + KYC.escapeHtml(c) + "</span></span>",
        '<span class="state-row-meta">' + KYC.escapeHtml(seats.join(", ")) + "</span>",
        off
          ? '<span class="state-row-meta">' + KYC.escapeHtml(off) + '</span><span class="state-row-meta"></span>'
          : '<span class="state-row-meta">' + KYC.escapeHtml(plural(info.seatsUp, "seat") +
            (KYC.recordPhase() ? " on the 2026 ballot" : " up")) +
            (info.open ? " &middot; " + KYC.escapeHtml(plural(info.open, "open seat")) : "") + "</span>" +
            '<span class="state-row-meta">' +
            KYC.escapeHtml(challengerWords(info, KYC.recordPhase()).join(" · ")) + "</span>",
        "</a>",
      ].join("");
    });

    target.innerHTML = [
      '<header class="state-hero">',
      '<h1 class="state-title">States &amp; territories</h1>',
      '<p class="state-summary">One page each: who holds the seats, the 2026 races, and everyone who has filed.</p>',
      "</header>",
      '<div class="state-list" id="stateList">' + rows.join("") + "</div>",
    ].join("");
  }

  /* --------------------------------------------------------------- chrome */

  function initSearch() {
    var input = el("stateSearch");
    if (!input) return;
    var run = KYC.debounce(function () {
      var q = input.value.trim().toLowerCase();
      if (kind === "states") {
        // Folded like every other search on the site (KYC.foldText).
        var folded = KYC.foldText(q);
        Array.prototype.forEach.call(doc.querySelectorAll(".state-row"), function (row) {
          row.hidden = !!folded && KYC.foldText(row.textContent).indexOf(folded) === -1;
        });
        return;
      }
      Array.prototype.forEach.call(doc.querySelectorAll("#stateContent .card"), function (c) {
        var item = KYC.byId(c.getAttribute("data-id"));
        c.hidden = !!q && !(item && KYC.matchesQuery(item, q));
      });
    }, 120);
    input.addEventListener("input", run);
  }

  function initCards() {
    el("stateContent").addEventListener("click", function (event) {
      // A jump within the page scrolls there and leaves the address alone.
      // A fragment left in it sent the reader back to that section when a
      // profile closed, however far they had read on (as jumpToSection says).
      var jump = event.target.closest('.jump-row a[href^="#"], a.state-jump[href^="#"]');
      if (jump) {
        var target = doc.getElementById(jump.getAttribute("href").slice(1));
        if (target) {
          event.preventDefault();
          if (target.scrollIntoView) target.scrollIntoView({ block: "start" });
          if (target.focus) {
            if (!target.hasAttribute("tabindex")) target.setAttribute("tabindex", "-1");
            target.focus({ preventScroll: true });
          }
        }
        return;
      }
      var card = event.target.closest("[data-id]");
      if (card) KYC.profile.open(card.getAttribute("data-id"));
    });
  }

  function applyRoute(route) {
    if (route.view === "profile" && KYC.profile.open(route.id, { fromRoute: true })) return;
    if (KYC.profile.isOpen()) KYC.profile.close();
  }

  KYC.ready(function () {
    if (!data.length) {
      el("stateContent").innerHTML =
        '<p class="results-bar">Profile data did not load. Run: python build_profile_site.py</p>';
      return;
    }
    KYC.profile.ensure();
    if (kind === "states") renderIndex(); else { renderState(); jumpToSection(); }
    initSearch();
    initCards();
    KYC.router.onChange(function () { applyRoute(KYC.router.read()); });
    applyRoute(KYC.router.read());
  });
})(window);
